    <script>
        /* ========== 获取消息内容 ========== */
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) {
                return null;
            }
            return chatMessages[0].message;
        }

        /* ========== 提取指定区块内容 ========== */
        function extractBlock(text, blockName) {
            var regex = new RegExp('<' + blockName + '>([\\s\\S]*?)<\\/' + blockName + '>');
            var match = text.match(regex);
            return match && match[1] ? match[1] : '';
        }

        /* ========== 解析 [字段|值] 数据 ========== */
        function parseFields(blockText) {
            var result = {};
            var regex = /\[(.*?)\|(.*?)\]/g;
            var match;
            while ((match = regex.exec(blockText)) !== null) {
                var key = match[1].trim();
                var val = match[2].trim();
                result[key] = val;
            }
            return result;
        }

        /* ========== 渲染界面 ========== */
        function renderPage(data) {
            /* 1. 顶部数据 */
            var time = data.top['当前时间'] || '未知时间';
            var location = data.top['所在地点'] || '未知地点';

            /* 2. 角色数据 */
            var charName = data.char['姓名'] || '暂无目标';
            var charAppearance = data.char['种族与外貌'] || '--';
            var charTraits = data.char['核心性格'] || '--';
            var charXP = data.char['隐藏XP'] || '--';
            var charBackground = data.char['背景故事'] || '--';
            var charCollar = data.char['项圈状态'] || '--';
            var charMaster = data.char['主人归属'] || '--';
            var charLove = data.char['婚恋状态'] || '--';
            var charStatus = data.char['当前状态'] || '--';

            /* 3. 产业数据 */
            var estateUnlocked = (data.estate['解锁状态'] === '已解锁');
            var estateName = data.estate['拥有产业'] || '--';
            var estateBldg = data.estate['建筑与功能'] || '--';
            var estateFunds = data.estate['当前资金'] || '0';
            var estateAttitude = data.estate['居民态度'] || '--';
            var estateIssue = data.estate['面临问题'] || '--';
            var estateVisit = data.estate['莉亚下次视察'] || '--';

            /* 组装 HTML */
            var html = '<div class="status-container">';

            /* 顶部栏 */
            html += '<div class="top-bar">';
            html += '  <span class="top-item">' + time + '</span>';
            html += '  <span class="top-item">' + location + '</span>';
            html += '</div>';

            html += '<div class="content-area">';

            /* 左侧角色面板 */
            html += '  <div class="char-panel">';
            html += '    <div class="panel-title">观测目标档案</div>';
            html += '    <div class="data-row"><span class="label">姓名</span><span class="val val-highlight">' + charName + '</span></div>';
            html += '    <div class="data-row"><span class="label">种族外貌</span><span class="val">' + charAppearance + '</span></div>';
            html += '    <div class="data-row"><span class="label">背景履历</span><span class="val" style="font-size:12px;color:#bbb;">' + charBackground + '</span></div>';
            html += '    <div class="data-row"><span class="label">性格</span><span class="val">' + charTraits + '</span></div>';
            html += '    <div class="data-row"><span class="label">深层渴望</span><span class="val val-highlight">' + charXP + '</span></div>';

            html += '    <div style="border-top: 1px dashed rgba(226, 88, 110, 0.3); margin: 6px 0; padding-top: 6px;"></div>'; /* 分隔线 */

            html += '    <div class="data-row"><span class="label">项圈状态</span><span class="val">' + charCollar + '</span></div>';
            html += '    <div class="data-row"><span class="label">主人归属</span><span class="val">' + charMaster + '</span></div>';
            html += '    <div class="data-row"><span class="label">婚恋羁绊</span><span class="val val-sub">' + charLove + '</span></div>';

            html += '    <div style="border-top: 1px dashed rgba(226, 88, 110, 0.3); margin: 6px 0; padding-top: 6px;"></div>'; /* 分隔线 */

            html += '    <div class="data-row"><span class="label">当前状态</span><span class="val" style="color:#aaa;">' + charStatus + '</span></div>';
            html += '  </div>';

            /* 右侧产业面板 */
            if (estateUnlocked) {
                html += '  <div class="estate-panel" style="display:block;">';
                html += '    <div class="panel-title">领地统辖状态</div>';
                html += '    <div class="data-row"><span class="label">当前产业</span><span class="val">' + estateName + '</span></div>';
                html += '    <div class="data-row"><span class="label">账面资金</span><span class="val" style="color:#f2c94c;">' + estateFunds + '</span></div>';
                html += '    <div class="data-row"><span class="label">建筑设施</span><span class="val">' + estateBldg + '</span></div>';
                html += '    <div class="data-row"><span class="label">居民态度</span><span class="val">' + estateAttitude + '</span></div>';
                html += '    <div class="data-row"><span class="label">面临危机</span><span class="val">' + estateIssue + '</span></div>';
                html += '    <div class="warning-box">⚠ 莉亚下次视察：' + estateVisit + ' <br><span style="font-size:11px;color:#999;">(视察绑定新建设施的肉体验收)</span></div>';
                html += '  </div>';
            } else {
                html = html.replace('border-right: 1px dashed #5a1f28;', '');
            }

            html += '</div>';
            html += '</div>';

            document.getElementById('content').innerHTML = html;
        }

        /* ========== 主函数 ========== */
        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById('content').innerHTML = '<div class="loading">❌ 无法获取状态信息</div>';
                    return;
                }

                var fullTagContent = extractBlock(messageText, 'STATUSBAR_DATA');
                if (!fullTagContent) {
                    document.getElementById('content').innerHTML = '<div class="loading" style="display:none;">未检测到状态标签</div>';
                    return;
                }

                var topBlock = extractBlock(fullTagContent, 'top_info');
                var charBlock = extractBlock(fullTagContent, 'character_info');
                var estateBlock = extractBlock(fullTagContent, 'estate_info');

                var data = {
                    top: parseFields(topBlock),
                    char: parseFields(charBlock),
                    estate: parseFields(estateBlock)
                };

                renderPage(data);
            } catch (error) {
                console.error("界面渲染错误:", error);
                document.getElementById('content').innerHTML = '<div class="loading">❌ 数据解析异常</div>';
            }
        }

        $(function() { init(); });
    </script>
</body>
</html>
